mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM broadcast_sessions
    WHERE id = #{sessionId}
      AND streamer_id = #{streamerId}
)

mapper.update:
UPDATE recordings
SET base_wall_clock  = #{baseWallClock},
    base_timecode_ms = #{baseTimecodeMs}
WHERE session_id = #{sessionId}
  AND status = 'RECORDING'

UPDATE recordings
SET ended_at    = #{endedAt},
    output_path = #{outputPath},
    status      = #{status}
WHERE session_id = #{sessionId}
